<template>
  <div class="app-container">
    <div class="page-hero"><div class="hero-inner"><div class="hero-text"><h1 class="hero-title">游程检验（二分类变量）</h1><p class="hero-desc">检验二分类序列是否具有随机性。通过计算游程数（连续相同类别的段数）并与期望游程数比较，游程数过多表示交替频繁，过少表示聚集趋势，两者都说明序列非随机</p></div><el-tag class="hero-tag" effect="dark" round>RUNS TEST · BINARY</el-tag></div></div>
    <el-row :gutter="20" class="mb-4 input-row">
      <el-col :lg="16" :xs="24"><el-card shadow="never" class="input-card"><el-form label-position="top"><el-form-item label="二分类序列（逗号分隔，如：男,女,男,男,女 或 1,0,1,1,0）"><el-input v-model="form.rawData" type="textarea" :rows="3" /></el-form-item></el-form><div class="action-bar"><el-button type="primary" class="calc-btn" @click="calculate"><el-icon class="mr-1"><DataAnalysis /></el-icon>开始计算</el-button><el-button class="reset-btn" @click="loadDemo">加载示例</el-button><el-button class="reset-btn" @click="clearAll">清除</el-button></div></el-card></el-col>
      <el-col :lg="8" :xs="24"><div class="param-sidebar"><div class="param-sidebar-header"><el-icon class="sidebar-icon"><InfoFilled /></el-icon>检验原理</div><div class="principle-content"><div class="principle-block"><div class="principle-label">假设检验</div><p>H₀: 序列是随机排列的</p></div><div class="principle-block"><div class="principle-label">游程</div><p>游程 = 连续相同类别构成的一段</p><div class="formula-box">Z = (R − E(R)) / SD(R)</div></div></div><div class="ref-section"><div class="ref-title">参考文献</div><p class="ref-item">[1] 方积乾.《卫生统计学》第7版, 2012.</p><p class="ref-item">[2] Wald A, Wolfowitz J. Ann Math Stat, 1940.</p></div></div></el-col>
    </el-row>
    <transition name="result-fade"><div v-if="res" class="result-section"><div class="metrics-grid mb-5"><div v-for="m in metrics" :key="m.label" class="metric-card" :class="m.type"><div class="metric-indicator" /><div class="metric-label">{{ m.label }}</div><div class="metric-value">{{ m.value }}</div></div></div><el-card shadow="never" class="detail-card mb-4"><template #header><div class="card-header-inner"><el-icon class="header-icon"><ChatLineSquare /></el-icon><span class="font-bold">结果解读</span></div></template><div class="narrative-body" v-html="narrative" /></el-card></div></transition>
  </div>
</template>
<script setup lang="ts">
import { InfoFilled, DataAnalysis, ChatLineSquare } from "@element-plus/icons-vue"; import * as S from "../utils/stats";
defineOptions({ name: "RunsBinary" }); const form = reactive({ rawData: "" }); const res = ref(false); const metrics = ref<any[]>([]); const narrative = ref("");
function loadDemo() { form.rawData = "男,女,男,男,女,女,男,女,男,男,男,女,女,男,女,男,男,女,女,女"; calculate(); }
function clearAll() { form.rawData = ""; res.value = false; }
function calculate() {
  const items = form.rawData.replace(/[，、；\n\r\t]+/g, ",").split(",").map(s => s.trim()).filter(s => s);
  if (items.length < 4) { ElMessage.warning("至少4个元素"); return; }
  const types = [...new Set(items)]; if (types.length !== 2) { ElMessage.warning("必须恰好2种类别"); return; }
  const n1 = items.filter(x => x === types[0]).length, n2 = items.filter(x => x === types[1]).length;
  let runs = 1; for (let i = 1; i < items.length; i++) { if (items[i] !== items[i - 1]) runs++; }
  const N = n1 + n2, meanR = 2 * n1 * n2 / N + 1, sdR = Math.sqrt(2 * n1 * n2 * (2 * n1 * n2 - N) / (N * N * (N - 1)));
  const z = sdR > 0 ? (runs - meanR) / sdR : 0; const pVal = 2 * (1 - S.normCDF(Math.abs(z))); const sig = pVal < 0.05;
  res.value = true;
  metrics.value = [{ label: `"${types[0]}"数`, value: n1, type: "accent" }, { label: `"${types[1]}"数`, value: n2, type: "accent" }, { label: "游程数 R", value: runs, type: "success" }, { label: "期望游程", value: S.fmt(meanR, 2), type: "success" }, { label: "Z", value: S.fmt(z), type: "warning" }, { label: "P", value: S.fmtP(pVal), type: sig ? "warning" : "neutral" }];
  narrative.value = `<p>"${types[0]}" = ${n1} 个，"${types[1]}" = ${n2} 个，游程数 R = <strong>${runs}</strong>，期望 = ${S.fmt(meanR, 2)}。</p><p>Z = <strong>${S.fmt(z)}</strong>，P = <strong>${S.fmtP(pVal)}</strong>。${sig ? "<strong>序列非随机</strong>。" : "不能拒绝随机性假设。"}</p>`;
}
</script>
